import json
import re
import sys

status="invalid"; failureCode="400"; failureMessage="Input validation failed"; failureError="One or more delete inputs are invalid."; failureResult="{}"
organizationName=sys.argv[1].strip(); deploymentName=sys.argv[2].strip(); confirmDeletion=sys.argv[3].strip().lower()=="true"; errors=[]
if not organizationName: errors.append("Workload Organization must not be blank.")
if not re.fullmatch(r"[a-zA-Z0-9][a-zA-Z0-9\- _]{0,31}",deploymentName): errors.append("Workload Deployment Name is invalid.")
if not confirmDeletion: errors.append("Confirm Deletion must be true.")
escapedOrganizationName=organizationName.replace("'","''"); escapedDeploymentName=deploymentName.replace("'","''")
if errors: failureError=" ".join(errors); failureResult=json.dumps({"error":failureMessage,"details":failureError},separators=(",",":"))
else: status="ready"; failureCode=failureMessage=failureError=""; failureResult="{}"

import json
import sys
status="invalid"; failureCode="502"; failureMessage="Workload instance count was invalid"; failureError="The filtered instance count could not be validated."; failureResult="{}"; instanceCount=""
try:
    envelope=json.loads(sys.argv[1]); results=envelope.get("Results") if isinstance(envelope,dict) else None; count=envelope.get("Count") if isinstance(envelope,dict) else None
    if not isinstance(results,list) or isinstance(count,bool) or not isinstance(count,int) or count<0: raise ValueError("Response must contain Results and a nonnegative integer Count.")
    instanceCount=str(count)
    if count!=0 or len(results)!=0:
        failureCode="409"; failureMessage="Workload deployment still has instances"; failureError="Deletion requires a zero filtered WorkloadInstances count."; failureResult=json.dumps({"error":failureMessage,"instanceCount":count,"recordsReturnedToCaller":False,"mutationSent":False},separators=(",",":"))
    else: status="ready"; failureCode=failureMessage=failureError=""; failureResult="{}"
except Exception as exc:
    failureError="The workload-instance count failed validation: "+str(exc); failureResult=json.dumps({"error":failureMessage,"details":failureError,"mutationSent":False},separators=(",",":"))
